import {CREW,CORES,SUPPORTS,compileLoadoutTechnique} from './mako.js?v=5.16.0';
import {nodesFor,nodeState,availablePoints,unlockNode} from './skill-grid-model.js?v=5.16.0';
import {RARE_MAKO,ownsRelic,isMakoAttuned,equipRareMako} from './wayglass-model.js?v=5.11.0';
import {SCHOOLS,learnedSchool,equipSchool,schoolMatches} from './constellation-model.js';
/** Free housekeeping only. Never spend growth, buy, replace a chosen move or choose a fork. */
export function settleCrewSetup(s){if(s.mode==='battle'||s.story&&!s.story.firstCore)return[];const receipts=[];const setup=s.crewSetup??={version:1,recent:[],freeNodes:{}};setup.freeNodes??={};for(const id of s.recruited||[]){const h=s.heroes[id];for(const n of nodesFor(id).filter(n=>n.stat==='skill'&&(h.learned&(1<<(7-n.step))))){s.skillGrid??={};s.skillGrid[id]??=[];if(!s.skillGrid[id].includes(n.id)){s.skillGrid[id].push(n.id);(setup.freeNodes[id]??=[]).push(n.id);}}const core=s.cores.includes(CREW[id].affinity)?CREW[id].affinity:s.cores.length===1?s.cores[0]:null,support=s.supports.includes('focus')?'focus':s.supports.length===1?s.supports[0]:null;h.loadout??=[];if(core&&support)for(let i=0;i<Math.min(3,h.unlockedSlots||h.loadout.length);i++)if(!h.loadout[i]){h.loadout[i]={core,support};receipts.push(h.name+' · socket '+(i+1)+' ready');}for(const r of RARE_MAKO){if(!isMakoAttuned(s,id,r.id)||h.loadout.some(x=>x?.makoId===r.id))continue;const i=h.loadout.findIndex(x=>x?.core===r.core&&!x.makoId);if(i>=0&&equipRareMako(s,id,i,r.id))receipts.push(h.name+' · '+r.name+' applied');}}return receipts;}
export function growthChoices(s,id){return nodesFor(id).filter(n=>!n.doctrine&&n.stat!=='mako'&&n.id!=='origin'&&nodeState(s,id,n)==='available').map(n=>({...n,points:availablePoints(s,id)}));}
export function rarePlan(s,id,makoId){const r=RARE_MAKO.find(x=>x.id===makoId),nodes=nodesFor(id),target=nodes.find(n=>n.makoId===makoId);if(!r||!target||!ownsRelic(s,r.id)||!s.cores.includes(r.core))return null;const own=new Set(s.skillGrid?.[id]||[]),chain=[];let n=target;while(n&&n.id!=='origin'&&!own.has(n.id)){chain.unshift(n);n=nodes.find(v=>v.id===n.requires);}const cost=chain.reduce((a,n)=>a+n.cost,0);return{rare:r,chain,cost,ready:(s.chapter>=2||s.complete)&&cost<=availablePoints(s,id),attuned:isMakoAttuned(s,id,makoId)};}
export function learnAndFitRare(s,id,makoId,index){const plan=rarePlan(s,id,makoId),slot=s.heroes[id]?.loadout?.[index];if(s.mode==='battle'||!s.recruited.includes(id)||!plan?.ready||!slot)return false; // A clone validates the whole transaction before any points change.
const copy=JSON.parse(JSON.stringify(s));for(const n of plan.chain)if(!unlockNode(copy,id,n.id))return false;if(!equipRareMako(copy,id,index,makoId))return false;for(const key of ['heroes','skillGrid'])if(copy[key])s[key]=copy[key];return true;}
export function learnAndWearSchool(s,id,schoolId){if(s.mode==='battle')return false;const node=nodesFor(id).find(n=>n.id==='discipline:'+schoolId+':root');if(!node)return false;const copy=JSON.parse(JSON.stringify(s));if(!learnedSchool(copy,id,schoolId).root&&!unlockNode(copy,id,node.id))return false;const slots=copy.heroes[id].doctrineSlots||[null,null],index=[0,1].find(i=>!slots[i]);if(index===undefined||!equipSchool(copy,id,schoolId,index))return false;s.heroes=copy.heroes;s.skillGrid=copy.skillGrid;return true;}
export function setupSnapshot(s){const result={};for(const core of s.cores||[])result['core:'+core]=CORES.find(c=>c.id===core)?.name+' core';for(const support of s.supports||[])result['support:'+support]=SUPPORTS.find(c=>c.id===support)?.name+' pattern';for(const id of s.recruited||[]){const h=s.heroes[id];result['hero:'+id]=h.name+' joins the crew';result['level:'+id]=h.level;for(const core of new Set((h.loadout||[]).map(x=>x.core))){const ap=h.ap?.[core]||0;result['rank:'+id+':'+core]=ap>=120?3:ap>=35?2:1;}result['slots:'+id]=h.unlockedSlots||h.loadout.length;result['growth:'+id]=availablePoints(s,id);}for(const r of RARE_MAKO)if(ownsRelic(s,r.id))result['rare:'+r.id]=r.name;for(const id of s.rivals?.gear||[])result['gear:'+id]=id.replaceAll('-',' ')+' gear';return result;}
export function collectSetupUnlocks(s){const now=setupSnapshot(s),p=s.crewSetup??={version:1,seen:now,recent:[]};if(!p.seen){p.seen=now;return[];}const changes=[];for(const [key,value]of Object.entries(now)){const old=p.seen[key],hero=s.heroes[Number(key.split(':')[1])];if(typeof value==='string'&&old===undefined)changes.push(value+' discovered');else if(old!==undefined&&typeof value==='number'&&value>old){if(key.startsWith('rank:'))changes.push(hero.name+' · '+key.split(':')[2]+' rank '+value+' active');if(key.startsWith('slots:'))changes.push(hero.name+' · new linked socket');if(key.startsWith('growth:'))changes.push(hero.name+' · +'+(value-old)+' growth to choose');}}p.seen=now;if(changes.length)p.recent=[...changes,...(p.recent||[])].slice(0,8);return changes;}
export function moveSummary(s,id,index){const h=s.heroes[id],slot=h.loadout[index];if(!slot)return null;const t=compileLoadoutTechnique(slot,h,s);return{...t,notes:[t.healing?'Restores allies':'Strikes enemies',t.interrupt?'Breaks charged attacks':null,t.echo?'Repeats after a delay':null,t.field?'Leaves a lingering field':null,t.counter?'Answers an incoming hit':null,t.link?'Uses a partner’s focus':null,...(t.doctrines||[]).map(d=>SCHOOLS.find(x=>x.id===d.id)?.name)].filter(Boolean)};}
export function matchingSchools(s,id){const h=s.heroes[id];return SCHOOLS.filter(school=>h.loadout.some(slot=>schoolMatches(school,slot)));}
